// Partner Invoices Retrieval
// Fetches partner invoices from Partner Center API

var accessToken = input.get("accessToken");

if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        var url = "https://api.partnercenter.microsoft.com/v1/invoices";

        log.info("Fetching partner invoices");

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var data = json.parse(response.body);

            output.set("TotalCount", data.totalCount || 0);

            var invoices = data.items || [];
            output.set("Invoices", json.stringify(invoices));
            output.set("InvoiceCount", invoices.length);

            // Extract summary data from most recent invoice (first in list)
            if (invoices.length > 0) {
                var latest = invoices[0];
                output.set("LatestInvoiceId", latest.id || "");
                output.set("LatestInvoiceDate", latest.invoiceDate || "");
                output.set("LatestBillingPeriodStart", latest.billingPeriodStartDate || "");
                output.set("LatestBillingPeriodEnd", latest.billingPeriodEndDate || "");
                output.set("LatestTotalCharges", latest.totalCharges || 0);
                output.set("LatestPaidAmount", latest.paidAmount || 0);
                output.set("LatestCurrencyCode", latest.currencyCode || "");
                output.set("LatestCurrencySymbol", latest.currencySymbol || "");
                output.set("LatestPdfLink", latest.pdfDownloadLink || "");
                output.set("LatestInvoiceType", latest.invoiceType || "");
                output.set("LatestDocumentType", latest.documentType || "");

                // Extract billing providers from invoice details
                var details = latest.invoiceDetails || [];
                var providers = [];
                for (var i = 0; i < details.length; i++) {
                    var provider = details[i].billingProvider;
                    if (provider && providers.indexOf(provider) === -1) {
                        providers.push(provider);
                    }
                }
                output.set("LatestBillingProviders", json.stringify(providers));
            } else {
                output.set("LatestInvoiceId", "");
                output.set("LatestInvoiceDate", "");
                output.set("LatestBillingPeriodStart", "");
                output.set("LatestBillingPeriodEnd", "");
                output.set("LatestTotalCharges", 0);
                output.set("LatestPaidAmount", 0);
                output.set("LatestCurrencyCode", "");
                output.set("LatestCurrencySymbol", "");
                output.set("LatestPdfLink", "");
                output.set("LatestInvoiceType", "");
                output.set("LatestDocumentType", "");
                output.set("LatestBillingProviders", "[]");
            }

            // Calculate totals across all invoices
            var totalChargesSum = 0;
            var totalPaidSum = 0;
            for (var j = 0; j < invoices.length; j++) {
                totalChargesSum += invoices[j].totalCharges || 0;
                totalPaidSum += invoices[j].paidAmount || 0;
            }
            output.set("AllInvoicesTotalCharges", totalChargesSum);
            output.set("AllInvoicesPaidAmount", totalPaidSum);
            output.set("AllInvoicesOutstanding", totalChargesSum - totalPaidSum);

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved " + invoices.length + " invoices");
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve invoices: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        tags.trigger("error");
    }
}
